// SQLite access through Drizzle (DATA-01) and versioned migrations (DATA-04).
import { fileURLToPath } from "node:url";
import Sqlite from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import type { BetterSQLite3Database } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import * as schema from "./schema.ts";

export type Db = BetterSQLite3Database<typeof schema>;

export interface Database {
  sqlite: Sqlite.Database;
  db: Db;
  close(): void;
}

/** Migrations shipped with the application (generated by drizzle-kit). */
export const MIGRATIONS_DIR = fileURLToPath(new URL("../../drizzle", import.meta.url));

const MIGRATIONS_TABLE = "__drizzle_migrations";

export function openDatabase(file: string): Database {
  const sqlite = new Sqlite(file);
  // WAL lets readers continue during writes and during online backups.
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  sqlite.pragma("busy_timeout = 5000");
  const db = drizzle(sqlite, { schema });
  // Transactions take the write lock when they begin (BEGIN IMMEDIATE), not at their first
  // write: a deferred transaction that has read and then writes while another process (the
  // CLI, a backup) committed fails at once with "database is locked", without waiting for
  // busy_timeout. Nested transactions are savepoints and are not affected.
  const transaction = db.transaction.bind(db);
  db.transaction = (run, config) => transaction(run, { behavior: "immediate", ...config });
  return { sqlite, db, close: () => sqlite.close() };
}

export class MigrationError extends Error {
  override name = "MigrationError";
}

function appliedCount(sqlite: Sqlite.Database): number {
  const table = sqlite
    .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?")
    .get(MIGRATIONS_TABLE);
  if (!table) return 0;
  const row = sqlite.prepare(`SELECT count(*) AS n FROM ${MIGRATIONS_TABLE}`).get() as {
    n: number;
  };
  return row.n;
}

/**
 * Applies all pending migrations in one transaction; on failure nothing is
 * applied and a MigrationError is thrown. Returns the number of migrations applied.
 */
export function runMigrations(database: Database, migrationsDir = MIGRATIONS_DIR): number {
  const before = appliedCount(database.sqlite);
  // SQLite changes a column by rebuilding its table, and dropping a table with foreign keys on
  // deletes what references it. So the migrations run with foreign keys off (the pragma does
  // nothing inside the transaction of the migrator, hence outside of it), and the keys are
  // checked afterwards.
  database.sqlite.pragma("foreign_keys = OFF");
  try {
    migrate(database.db, { migrationsFolder: migrationsDir, migrationsTable: MIGRATIONS_TABLE });
  } catch (error) {
    // Drizzle wraps the SQLite error; its cause names the failing statement.
    const root = error instanceof Error && error.cause instanceof Error ? error.cause : error;
    const reason = root instanceof Error ? root.message : String(root);
    throw new MigrationError(`database migration failed, nothing was applied: ${reason}`, {
      cause: error,
    });
  } finally {
    database.sqlite.pragma("foreign_keys = ON");
  }
  const broken = database.sqlite.pragma("foreign_key_check") as unknown[];
  if (broken.length > 0) {
    throw new MigrationError(
      `the migrations were applied, but ${String(broken.length)} rows break a foreign key: restore the backup taken before the update`,
    );
  }
  return appliedCount(database.sqlite) - before;
}
